import{_ as e,o as s,c as r,a4 as o,a8 as i,a9 as n,aa as l,ab as t,ac as d,ad as _}from"./chunks/framework.DAe4SYBh.js";const f=JSON.parse('{"title":"DVP Sensor 适配","description":"","frontmatter":{},"headers":[],"relativePath":"goke/v500/DVP Sensor适配.md","filePath":"goke/v500/DVP Sensor适配.md"}'),c={name:"goke/v500/DVP Sensor适配.md"};function h(m,a,p,P,b,S){return s(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="dvp-sensor-适配" tabindex="-1">DVP Sensor 适配 <a class="header-anchor" href="#dvp-sensor-适配" aria-label="Permalink to “DVP Sensor 适配”">​</a></h1><h2 id="环境" tabindex="-1">环境 <a class="header-anchor" href="#环境" aria-label="Permalink to “环境”">​</a></h2><ul><li>主板：7205V500</li><li>Sensor：GC4103（示例）</li><li>SDK：030</li></ul><h2 id="sensor-适配" tabindex="-1">Sensor 适配 <a class="header-anchor" href="#sensor-适配" aria-label="Permalink to “Sensor 适配”">​</a></h2><p>如果使用的 sensor 从未适配过，需要先适配 sensor 驱动，并确认 sensor 支持 DVP 输出。以 GC4103 为例，sample 中没有适配，需要新增驱动。</p><p>Sensor 适配详见《sensor_sample适配方法.pdf》。</p><h3 id="_1-修改-sample-comm-vi-getcomboattrbysns" tabindex="-1">1. 修改 SAMPLE_COMM_VI_GetComboAttrBySns <a class="header-anchor" href="#_1-修改-sample-comm-vi-getcomboattrbysns" aria-label="Permalink to “1. 修改 SAMPLE_COMM_VI_GetComboAttrBySns”">​</a></h3><p>修改对应 sensor 的 input mode，DVP 需要改为 <code>INPUT_MODE_CMOS</code>。</p><p><img src="'+i+'" alt="input mode 修改为 INPUT_MODE_CMOS"></p><h3 id="_2-修改-sample-comm-vi-getdevattrbysns-参数" tabindex="-1">2. 修改 SAMPLE_COMM_VI_GetDevAttrBySns 参数 <a class="header-anchor" href="#_2-修改-sample-comm-vi-getdevattrbysns-参数" aria-label="Permalink to “2. 修改 SAMPLE_COMM_VI_GetDevAttrBySns 参数”">​</a></h3><p>设置为 <code>VI_MODE_DIGITAL_CAMERA</code>。</p><p><img src="'+n+'" alt="VI_MODE_DIGITAL_CAMERA 配置"></p><h2 id="引脚复用" tabindex="-1">引脚复用 <a class="header-anchor" href="#引脚复用" aria-label="Permalink to “引脚复用”">​</a></h2><p>开发板从 MIPI 输出改为 DVP 输出，需要修改对应 I2C、sensor、VI 引脚复用。以 7205V500 主板 + GC4103 sensor 为例，复用请以实际硬件为准。</p><p>修改代码位置：<code>source/gmp/modules/sysconfig/sys_config.c</code></p><h3 id="_1-i2c-引脚复用修改" tabindex="-1">1. I2C 引脚复用修改 <a class="header-anchor" href="#_1-i2c-引脚复用修改" aria-label="Permalink to “1. I2C 引脚复用修改”">​</a></h3><p><img src="'+l+'" alt="I2C 引脚复用修改"></p><h3 id="_2-sensor-引脚复用修改" tabindex="-1">2. Sensor 引脚复用修改 <a class="header-anchor" href="#_2-sensor-引脚复用修改" aria-label="Permalink to “2. Sensor 引脚复用修改”">​</a></h3><p><img src="'+t+'" alt="Sensor 引脚复用修改"></p><h3 id="_3-vi-相关引脚复用" tabindex="-1">3. VI 相关引脚复用 <a class="header-anchor" href="#_3-vi-相关引脚复用" aria-label="Permalink to “3. VI 相关引脚复用”">​</a></h3><p><img src="'+d+'" alt="VI 相关引脚复用"></p><h3 id="_4-load-参数修改" tabindex="-1">4. load 参数修改 <a class="header-anchor" href="#_4-load-参数修改" aria-label="Permalink to “4. load 参数修改”">​</a></h3><p>在串口加载驱动时，修改 load 参数：<code>./load xm72050200 -i -sensor gc4023 -osmem 32 -board demo -yuv0 1</code>，其中 <code>-yuv0</code> 为 1 时才是 DVP 输出。</p><p><img src="'+_+'" alt="load 参数修改"></p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h2><h3 id="_1-初始化-sensor-报错-i2c-写入错误" tabindex="-1">1. 初始化 sensor 报错 I2C 写入错误 <a class="header-anchor" href="#_1-初始化-sensor-报错-i2c-写入错误" aria-label="Permalink to “1. 初始化 sensor 报错 I2C 写入错误”">​</a></h3><ul><li>确认管脚复用是否配置正确。</li><li>确认硬件是否 OK。以 V500 主板为例，需要硬件上修改才能复用管脚。</li></ul><h3 id="_2-vpss-输出帧率与预期不符" tabindex="-1">2. VPSS 输出帧率与预期不符 <a class="header-anchor" href="#_2-vpss-输出帧率与预期不符" aria-label="Permalink to “2. VPSS 输出帧率与预期不符”">​</a></h3><ul><li>调整 sensor 时钟。</li></ul>',29)])])}const I=e(c,[["render",h]]);export{f as __pageData,I as default};
